def make_uni_object(row):
    (uid, name, short_name, country, city, continent, qs, utype, website, t_intl, t_dom, curr, living, app_fee, ielts, toefl, duolingo, gpa, majors, desc, year, pop, intl_pop, accept_rate, campus, climate, emp_rate) = row
    
    domain = re.sub(r'^https?://(www\.)?', '', website).split('/')[0]
    
    return {
        "id": uid,
        "name": name,
        "shortName": short_name,
        "country": country,
        "city": city,
        "continent": continent,
        "worldRanking": qs,
        "qsRanking": qs,
        "theRanking": qs + 2 if qs else None,
        "type": utype,
        "website": website,
        "logo": f"https://logo.clearbit.com/{domain}",
        "heroImage": "https://images.unsplash.com/photo-1541339907198-e08756dedf3f?auto=format&fit=crop&w=1200&q=80",
        "acceptanceRate": accept_rate,
        "studentPopulation": pop,
        "internationalStudents": intl_pop,
        "founded": year,
        "tuition": {
            "international": t_intl,
            "domestic": t_dom,
            "currency": curr
        },
        "livingCostPerYear": {
            "amount": living,
            "currency": curr
        },
        "applicationFee": {
            "amount": app_fee,
            "currency": curr
        },
        "applicationDeadlines": {
            "earlyAction": "November 1" if country == "United States" else None,
            "regularDecision": "January 15" if country == "United States" else "February 1",
            "spring": "October 1"
        },
        "languageRequirements": {
            "ielts": ielts,
            "toefl": toefl,
            "duolingo": duolingo
        },
        "minimumGPA": gpa,
        "popularMajors": majors,
        "availableDegrees": ["Bachelor", "Master", "PhD"],
        "scholarshipsAvailable": True,
        "description": desc,
        "campusType": campus,
        "climate": climate,
        "employmentRate": emp_rate,
        "officialSocials": {
            "facebook": f"https://facebook.com/{uid}",
            "instagram": f"https://instagram.com/{uid}",
            "linkedin": f"https://linkedin.com/school/{uid}",
            "youtube": f"https://youtube.com/c/{uid}"
        }
    }

print("Base Python script created.")
